     1→/**
     2→ * Idea CRUD Operations
     3→ *
     4→ * Create, Read, Update, Delete operations for ideas.
     5→ * Used by both CLI and API endpoints.
     6→ */
     7→
     8→import { createTask, type CreateTaskOptions } from "../../task/ops/crud";
     9→
    10→import {
    11→  type Idea,
    12→  type IdeaListOptions,
    13→  type IdeaPromoteOptions,
    14→  type IdeaRemoveOptions,
    15→  type IdeaListResult,
    16→  type IdeaViewResult,
    17→  type IdeaPromoteResult,
    18→  type IdeaRemoveResult,
    19→  type IdeaListTypesResult,
    20→  type IdeaTypeInput,
    21→  type IdeaTypeCreateResult,
    22→  type IdeaTypeUpdateResult,
    23→  type IdeaTypeDeleteResult,
    24→  type EffortLevel,
    25→  EFFORT_PRIORITY_MAP,
    26→  isValidEffortLevel,
    27→  isValidIdeaStatus,
    28→  EFFORT_LEVELS,
    29→  IDEA_STATUSES,
    30→  DEFAULT_MAX_IDEAS,
    31→} from "./types";
    32→
    33→import {
    34→  listIdeaTypes,
    35→  getIdeaType,
    36→  getAllIdeas,
    37→  getIdeaById,
    38→  findIdeaById,
    39→  updateIdeaStatus,
    40→  removeIdea,
    41→  removeIdeasByType,
    42→  removeAllIdeas,
    43→  getIdeaTypesDir,
    44→  createIdeaType as createIdeaTypeFile,
    45→  updateIdeaType as updateIdeaTypeFile,
    46→  deleteIdeaType as deleteIdeaTypeFile,
    47→} from "./store";
    48→
    49→// =============================================================================
    50→// List Ideas
    51→// =============================================================================
    52→
    53→/**
    54→ * List all ideas with optional filtering
    55→ *
    56→ * @param repoRoot - Repository root path
    57→ * @param options - Filter options
    58→ * @returns List of ideas
    59→ */
    60→export function listIdeas(
    61→  repoRoot: string,
    62→  options?: IdeaListOptions
    63→): IdeaListResult {
    64→  try {
    65→    // Validate filters
    66→    if (options?.effort && !isValidEffortLevel(options.effort)) {
    67→      return {
    68→        success: false,
    69→        ideas: [],
    70→        count: 0,
    71→        error: `Invalid effort level. Must be one of: ${EFFORT_LEVELS.join(", ")}`,
    72→      };
    73→    }
    74→
    75→    if (options?.status && !isValidIdeaStatus(options.status)) {
    76→      return {
    77→        success: false,
    78→        ideas: [],
    79→        count: 0,
    80→        error: `Invalid status. Must be one of: ${IDEA_STATUSES.join(", ")}`,
    81→      };
    82→    }
    83→
    84→    const ideas = getAllIdeas(repoRoot, options);
    85→
    86→    return {
    87→      success: true,
    88→      ideas,
    89→      count: ideas.length,
    90→    };
    91→  } catch (error) {
    92→    return {
    93→      success: false,
    94→      ideas: [],
    95→      count: 0,
    96→      error: error instanceof Error ? error.message : String(error),
    97→    };
    98→  }
    99→}
   100→
   101→// =============================================================================
   102→// List Idea Types
   103→// =============================================================================
   104→
   105→/**
   106→ * List all available idea types (builtin + custom)
   107→ *
   108→ * @param repoRoot - Repository root path
   109→ * @returns List of idea types
   110→ */
   111→export function listTypes(repoRoot: string): IdeaListTypesResult {
   112→  try {
   113→    const types = listIdeaTypes(repoRoot);
   114→
   115→    return {
   116→      success: true,
   117→      types,
   118→      count: types.length,
   119→    };
   120→  } catch (error) {
   121→    return {
   122→      success: false,
   123→      types: [],
   124→      count: 0,
   125→      error: error instanceof Error ? error.message : String(error),
   126→    };
   127→  }
   128→}
   129→
   130→// =============================================================================
   131→// View Idea
   132→// =============================================================================
   133→
   134→/**
   135→ * Get idea details by ID
   136→ *
   137→ * @param repoRoot - Repository root path
   138→ * @param ideaId - Idea ID
   139→ * @returns Idea details
   140→ */
   141→export function viewIdea(repoRoot: string, ideaId: string): IdeaViewResult {
   142→  try {
   143→    const result = findIdeaById(repoRoot, ideaId);
   144→
   145→    if (!result) {
   146→      return {
   147→        success: false,
   148→        error: `Idea not found: ${ideaId}`,
   149→      };
   150→    }
   151→
   152→    return {
   153→      success: true,
   154→      idea: result.idea,
   155→      sessionDir: result.sessionDir,
   156→      filePath: result.filePath,
   157→    };
   158→  } catch (error) {
   159→    return {
   160→      success: false,
   161→      error: error instanceof Error ? error.message : String(error),
   162→    };
   163→  }
   164→}
   165→
   166→// =============================================================================
   167→// Promote Idea
   168→// =============================================================================
   169→
   170→/**
   171→ * Promote an idea to a task
   172→ *
   173→ * Creates a new task from an idea, using the idea's title and description.
   174→ * Updates the idea's status to "promoted" and links it to the created task.
   175→ *
   176→ * @param repoRoot - Repository root path
   177→ * @param ideaId - Idea ID to promote
   178→ * @param options - Task creation options
   179→ * @returns Promotion result
   180→ */
   181→export function promoteIdea(
   182→  repoRoot: string,
   183→  ideaId: string,
   184→  options: IdeaPromoteOptions = {}
   185→): IdeaPromoteResult {
   186→  try {
   187→    // Get idea first to validate and get effort for default priority
   188→    const idea = getIdeaById(repoRoot, ideaId);
   189→    if (!idea) {
   190→      return {
   191→        success: false,
   192→        error: `Idea not found: ${ideaId}`,
   193→      };
   194→    }
   195→
   196→    if (idea.status === "promoted") {
   197→      return {
   198→        success: false,
   199→        error: `Idea "${ideaId}" has already been promoted to task "${idea.promotedTo}"`,
   200→      };
   201→    }
   202→
   203→    // Use effort-based priority if not specified
   204→    const priority =
   205→      options.priority || EFFORT_PRIORITY_MAP[idea.estimatedEffort] || "medium";
   206→
   207→    // Create task using the idea's title
   208→    const taskOptions: CreateTaskOptions = {
   209→      slug: options.slug,
   210→      assignee: options.assignee,
   211→      priority,
   212→      description: options.description || idea.description,
   213→      branch: options.branch,
   214→      agent: options.agent,
   215→      executor: options.executor,
   216→      model: options.model,
   217→      start: options.start,
   218→      worktree: options.worktree,
   219→      computeReward: options.computeReward,
   220→      evoDir: options.evoDir,
   221→      // Pass idea ID for Evo reward path structure: iter{N}/{ideaId}/{taskName}/reward.json
   222→      evoIdea: options.evoIdea || idea.id,
   223→    };
   224→
   225→    const result = createTask(repoRoot, idea.title, taskOptions);
   226→
   227→    if (!result.success) {
   228→      return {
   229→        success: false,
   230→        error: result.error || "Failed to create task",
   231→      };
   232→    }
   233→
   234→    // Update idea status to promoted
   235→    updateIdeaStatus(repoRoot, idea.id, "promoted", result.dir_name);
   236→
   237→    return {
   238→      success: true,
   239→      idea_id: ideaId,
   240→      idea_title: idea.title,
   241→      task_id: result.dir_name,
   242→      task_dir: result.task_dir,
   243→      dir_name: result.dir_name,
   244→      priority,
   245→      status: options.start ? "queue" : "backlog",
   246→      worktree: options.worktree || false,
   247→    };
   248→  } catch (error) {
   249→    return {
   250→      success: false,
   251→      error: error instanceof Error ? error.message : String(error),
   252→    };
   253→  }
   254→}
   255→
   256→/**
   257→ * Promote an idea directly from an Idea object (without disk lookup)
   258→ *
   259→ * This is useful when you already have the Idea object in memory,
   260→ * such as after calling generateIdeas(). It bypasses the disk lookup
   261→ * that promoteIdea() does.
   262→ *
   263→ * @param repoRoot - Repository root path
   264→ * @param idea - Idea object to promote
   265→ * @param options - Task creation options
   266→ * @returns Promotion result
   267→ */
   268→export function promoteIdeaDirect(
   269→  repoRoot: string,
   270→  idea: Idea,
   271→  options: IdeaPromoteOptions = {}
   272→): IdeaPromoteResult {
   273→  try {
   274→    if (idea.status === "promoted") {
   275→      return {
   276→        success: false,
   277→        error: `Idea "${idea.id}" has already been promoted to task "${idea.promotedTo}"`,
   278→      };
   279→    }
   280→
   281→    // Use effort-based priority if not specified
   282→    const priority =
   283→      options.priority || EFFORT_PRIORITY_MAP[idea.estimatedEffort] || "medium";
   284→
   285→    // Create task using the idea's title
   286→    const taskOptions: CreateTaskOptions = {
   287→      slug: options.slug,
   288→      assignee: options.assignee,
   289→      priority,
   290→      description: options.description || idea.description,
   291→      branch: options.branch,
   292→      agent: options.agent,
   293→      executor: options.executor,
   294→      model: options.model,
   295→      start: options.start,
   296→      worktree: options.worktree,
   297→      computeReward: options.computeReward,
   298→      evoDir: options.evoDir,
   299→      // Pass idea ID for Evo reward path structure: iter{N}/{ideaId}/{taskName}/reward.json
   300→      evoIdea: options.evoIdea || idea.id,
   301→    };
   302→
   303→    const result = createTask(repoRoot, idea.title, taskOptions);
   304→
   305→    if (!result.success) {
   306→      return {
   307→        success: false,
   308→        error: result.error || "Failed to create task",
   309→      };
   310→    }
   311→
   312→    // Try to update idea status on disk (may fail if not persisted, that's OK)
   313→    try {
   314→      updateIdeaStatus(repoRoot, idea.id, "promoted", result.dir_name);
   315→    } catch {
   316→      // Ignore - idea may not be on disk yet
   317→    }
   318→
   319→    return {
   320→      success: true,
   321→      idea_id: idea.id,
   322→      idea_title: idea.title,
   323→      task_id: result.dir_name,
   324→      task_dir: result.task_dir,
   325→      dir_name: result.dir_name,
   326→      priority,
   327→      status: options.start ? "queue" : "backlog",
   328→      worktree: options.worktree || false,
   329→    };
   330→  } catch (error) {
   331→    return {
   332→      success: false,
   333→      error: error instanceof Error ? error.message : String(error),
   334→    };
   335→  }
   336→}
   337→
   338→// =============================================================================
   339→// Remove Ideas
   340→// =============================================================================
   341→
   342→/**
   343→ * Remove ideas by ID, type, or all
   344→ *
   345→ * @param repoRoot - Repository root path
   346→ * @param ideaIds - Array of idea IDs to remove (optional)
   347→ * @param options - Remove options
   348→ * @returns Remove result
   349→ */
   350→export function removeIdeas(
   351→  repoRoot: string,
   352→  ideaIds: string[] = [],
   353→  options: IdeaRemoveOptions = {}
   354→): IdeaRemoveResult {
   355→  try {
   356→    // Validate that at least one option is provided
   357→    if (!ideaIds.length && !options.type && !options.all) {
   358→      return {
   359→        success: false,
   360→        removed: [],
   361→        count: 0,
   362→        error: "Must specify idea IDs, --type, or --all",
   363→      };
   364→    }
   365→
   366→    let removedCount = 0;
   367→    const removedIds: string[] = [];
   368→
   369→    if (options.all) {
   370→      removedCount = removeAllIdeas(repoRoot);
   371→    } else if (options.type) {
   372→      removedCount = removeIdeasByType(repoRoot, options.type);
   373→    } else if (ideaIds.length > 0) {
   374→      for (const id of ideaIds) {
   375→        if (removeIdea(repoRoot, id)) {
   376→          removedIds.push(id);
   377→          removedCount++;
   378→        }
   379→      }
   380→    }
   381→
   382→    return {
   383→      success: true,
   384→      removed: removedIds,
   385→      count: removedCount,
   386→    };
   387→  } catch (error) {
   388→    return {
   389→      success: false,
   390→      removed: [],
   391→      count: 0,
   392→      error: error instanceof Error ? error.message : String(error),
   393→    };
   394→  }
   395→}
   396→
   397→// =============================================================================
   398→// Dismiss Idea
   399→// =============================================================================
   400→
   401→/**
   402→ * Dismiss an idea (mark as not worth pursuing)
   403→ *
   404→ * @param repoRoot - Repository root path
   405→ * @param ideaId - Idea ID to dismiss
   406→ * @returns Whether the idea was dismissed
   407→ */
   408→export function dismissIdea(
   409→  repoRoot: string,
   410→  ideaId: string
   411→): { success: boolean; error?: string } {
   412→  try {
   413→    const idea = getIdeaById(repoRoot, ideaId);
   414→    if (!idea) {
   415→      return {
   416→        success: false,
   417→        error: `Idea not found: ${ideaId}`,
   418→      };
   419→    }
   420→
   421→    if (idea.status === "promoted") {
   422→      return {
   423→        success: false,
   424→        error: `Cannot dismiss promoted idea "${ideaId}"`,
   425→      };
   426→    }
   427→
   428→    updateIdeaStatus(repoRoot, ideaId, "dismissed");
   429→
   430→    return { success: true };
   431→  } catch (error) {
   432→    return {
   433→      success: false,
   434→      error: error instanceof Error ? error.message : String(error),
   435→    };
   436→  }
   437→}
   438→
   439→// =============================================================================
   440→// Validate Idea Type
   441→// =============================================================================
   442→
   443→/**
   444→ * Validate that an idea type exists
   445→ *
   446→ * @param repoRoot - Repository root path
   447→ * @param typeName - Type name to validate
   448→ * @returns Whether the type exists
   449→ */
   450→export function validateIdeaType(
   451→  repoRoot: string,
   452→  typeName: string
   453→): { valid: boolean; error?: string } {
   454→  const ideaType = getIdeaType(typeName, repoRoot);
   455→  if (!ideaType) {
   456→    return {
   457→      valid: false,
   458→      error: `Unknown idea type: ${typeName}. Use "viben idea list-types" to see available types.`,
   459→    };
   460→  }
   461→  return { valid: true };
   462→}
   463→
   464→/**
   465→ * Validate multiple idea types
   466→ *
   467→ * @param repoRoot - Repository root path
   468→ * @param typeNames - Type names to validate
   469→ * @returns Validation result with invalid types
   470→ */
   471→export function validateIdeaTypes(
   472→  repoRoot: string,
   473→  typeNames: string[]
   474→): { valid: boolean; invalidTypes: string[] } {
   475→  const invalidTypes: string[] = [];
   476→
   477→  for (const typeName of typeNames) {
   478→    const ideaType = getIdeaType(typeName, repoRoot);
   479→    if (!ideaType) {
   480→      invalidTypes.push(typeName);
   481→    }
   482→  }
   483→
   484→  return {
   485→    valid: invalidTypes.length === 0,
   486→    invalidTypes,
   487→  };
   488→}
   489→
   490→// =============================================================================
   491→// Idea Type CRUD Operations
   492→// =============================================================================
   493→
   494→/**
   495→ * Create a new custom idea type
   496→ *
   497→ * Creates a new markdown file in docs/idea-types/ with YAML frontmatter.
   498→ *
   499→ * @param repoRoot - Repository root path
   500→ * @param input - Idea type input data
   501→ * @returns Creation result
   502→ */
   503→export function createIdeaTypeOp(
   504→  repoRoot: string,
   505→  input: IdeaTypeInput
   506→): IdeaTypeCreateResult {
   507→  try {
   508→    // Validate name (must be snake_case, no spaces)
   509→    if (!/^[a-z][a-z0-9_]*$/.test(input.name)) {
   510→      return {
   511→        success: false,
   512→        error: `Invalid type name "${input.name}". Must be lowercase letters, numbers, and underscores, starting with a letter.`,
   513→      };
   514→    }
   515→
   516→    // Check if type already exists
   517→    const existing = getIdeaType(input.name, repoRoot);
   518→    if (existing) {
   519→      return {
   520→        success: false,
   521→        error: `Idea type "${input.name}" already exists at ${existing.promptPath}`,
   522→      };
   523→    }
   524→
   525→    // Create the idea type
   526→    const ideaType = createIdeaTypeFile(repoRoot, {
   527→      name: input.name,
   528→      description: input.description,
   529→      maxIdeas: input.maxIdeas ?? DEFAULT_MAX_IDEAS,
   530→      promptContent: input.promptContent,
   531→    });
   532→
   533→    return {
   534→      success: true,
   535→      ideaType,
   536→    };
   537→  } catch (error) {
   538→    return {
   539→      success: false,
   540→      error: error instanceof Error ? error.message : String(error),
   541→    };
   542→  }
   543→}
   544→
   545→/**
   546→ * Update an existing custom idea type
   547→ *
   548→ * Only custom types (not builtin) can be updated.
   549→ *
   550→ * @param repoRoot - Repository root path
   551→ * @param typeName - Type name to update
   552→ * @param input - Updated data
   553→ * @returns Update result
   554→ */
   555→export function updateIdeaTypeOp(
   556→  repoRoot: string,
   557→  typeName: string,
   558→  input: Partial<IdeaTypeInput>
   559→): IdeaTypeUpdateResult {
   560→  try {
   561→    // Check if type exists
   562→    const existing = getIdeaType(typeName, repoRoot);
   563→    if (!existing) {
   564→      return {
   565→        success: false,
   566→        error: `Idea type "${typeName}" not found`,
   567→      };
   568→    }
   569→
   570→    // Builtin types can only be updated if they exist in docs/idea-types/
   571→    // (i.e., they were copied by `viben init`)
   572→    const typesDir = getIdeaTypesDir(repoRoot);
   573→    if (!existing.promptPath.startsWith(typesDir)) {
   574→      return {
   575→        success: false,
   576→        error: `Cannot update builtin type "${typeName}". Copy it to docs/idea-types/ first using "viben init".`,
   577→      };
   578→    }
   579→
   580→    // Update the idea type
   581→    const ideaType = updateIdeaTypeFile(repoRoot, typeName, {
   582→      description: input.description,
   583→      maxIdeas: input.maxIdeas,
   584→      promptContent: input.promptContent,
   585→    });
   586→
   587→    return {
   588→      success: true,
   589→      ideaType,
   590→    };
   591→  } catch (error) {
   592→    return {
   593→      success: false,
   594→      error: error instanceof Error ? error.message : String(error),
   595→    };
   596→  }
   597→}
   598→
   599→/**
   600→ * Delete a custom idea type
   601→ *
   602→ * Only custom types (not builtin from packages/core) can be deleted.
   603→ *
   604→ * @param repoRoot - Repository root path
   605→ * @param typeName - Type name to delete
   606→ * @returns Delete result
   607→ */
   608→export function deleteIdeaTypeOp(
   609→  repoRoot: string,
   610→  typeName: string
   611→): IdeaTypeDeleteResult {
   612→  try {
   613→    // Check if type exists
   614→    const existing = getIdeaType(typeName, repoRoot);
   615→    if (!existing) {
   616→      return {
   617→        success: false,
   618→        error: `Idea type "${typeName}" not found`,
   619→      };
   620→    }
   621→
   622→    // Only allow deleting types in docs/idea-types/
   623→    const typesDir = getIdeaTypesDir(repoRoot);
   624→    if (!existing.promptPath.startsWith(typesDir)) {
   625→      return {
   626→        success: false,
   627→        error: `Cannot delete builtin type "${typeName}". It is located in packages/core.`,
   628→      };
   629→    }
   630→
   631→    // Delete the file
   632→    deleteIdeaTypeFile(repoRoot, typeName);
   633→
   634→    return {
   635→      success: true,
   636→      name: typeName,
   637→    };
   638→  } catch (error) {
   639→    return {
   640→      success: false,
   641→      error: error instanceof Error ? error.message : String(error),
   642→    };
   643→  }
   644→}
