     1→/**
     2→ * Idea Types
     3→ *
     4→ * Type definitions for the idea module.
     5→ * Based on docs/specs/modules/cli/idea.md
     6→ */
     7→
     8→// =============================================================================
     9→// Constants
    10→// =============================================================================
    11→
    12→/**
    13→ * Built-in idea types that are shipped with viben
    14→ */
    15→export const BUILTIN_IDEA_TYPES = [
    16→  "code_improvements",
    17→  "code_quality",
    18→  "documentation_gaps",
    19→  "performance_optimizations",
    20→  "security_hardening",
    21→  "ui_ux_improvements",
    22→] as const;
    23→
    24→/**
    25→ * Type for built-in idea type names
    26→ */
    27→export type BuiltinIdeaTypeName = (typeof BUILTIN_IDEA_TYPES)[number];
    28→
    29→/**
    30→ * Effort levels for ideas
    31→ * Represents the estimated work required to implement an idea
    32→ */
    33→export const EFFORT_LEVELS = [
    34→  "trivial",
    35→  "small",
    36→  "medium",
    37→  "large",
    38→  "complex",
    39→] as const;
    40→
    41→/**
    42→ * Type for effort level values
    43→ */
    44→export type EffortLevel = (typeof EFFORT_LEVELS)[number];
    45→
    46→/**
    47→ * Idea statuses in the lifecycle
    48→ */
    49→export const IDEA_STATUSES = ["draft", "promoted", "dismissed"] as const;
    50→
    51→/**
    52→ * Type for idea status values
    53→ */
    54→export type IdeaStatus = (typeof IDEA_STATUSES)[number];
    55→
    56→/**
    57→ * Mapping from effort level to default priority when promoting to task
    58→ */
    59→export const EFFORT_PRIORITY_MAP: Record<EffortLevel, string> = {
    60→  trivial: "low",
    61→  small: "low",
    62→  medium: "medium",
    63→  large: "high",
    64→  complex: "high",
    65→};
    66→
    67→/**
    68→ * Default maximum ideas per type
    69→ */
    70→export const DEFAULT_MAX_IDEAS = 5;
    71→
    72→/**
    73→ * Ideas output directory relative to .viben
    74→ */
    75→export const IDEAS_DIR = "ideas";
    76→
