   628→/**
   629→ * Check if a string is a valid effort level
   630→ */
   631→export function isValidEffortLevel(value: string): value is EffortLevel {
   632→  return EFFORT_LEVELS.includes(value as EffortLevel);
   633→}
   634→
   635→/**
   636→ * Check if a string is a valid idea status
   637→ */
   638→export function isValidIdeaStatus(value: string): value is IdeaStatus {
   639→  return IDEA_STATUSES.includes(value as IdeaStatus);
   640→}
   641→
   642→/**
   643→ * Check if a string is a built-in idea type
   644→ */
   645→export function isBuiltinIdeaType(value: string): value is BuiltinIdeaTypeName {
   646→  return BUILTIN_IDEA_TYPES.includes(value as BuiltinIdeaTypeName);
   647→}
   648→
   649→/**
   650→ * Get the default priority for an effort level
   651→ */
   652→export function getDefaultPriority(effort: EffortLevel): string {
   653→  return EFFORT_PRIORITY_MAP[effort];
   654→}
   655→
   656→/**
   657→ * Generate idea ID prefix from type name
   658→ *
   659→ * @param typeName - Idea type name
   660→ * @returns Two-letter prefix (e.g., "ci" for code_improvements)
   661→ */
   662→export function getIdeaIdPrefix(typeName: string): string {
   663→  // Take first letter of each word, max 2 letters
   664→  const words = typeName.split("_");
   665→  if (words.length >= 2) {
   666→    return words[0][0] + words[1][0];
   667→  }
   668→  return typeName.slice(0, 2);
   669→}
