   671→/**
   672→ * Convert raw idea data from YAML to Idea interface
   673→ */
   674→export function parseRawIdea(raw: RawIdeaData): Idea {
   675→  return {
   676→    id: raw.id,
   677→    type: raw.type,
   678→    name: raw.name,
   679→    title: raw.title,
   680→    description: raw.description,
   681→    rationale: raw.rationale,
   682→    estimatedEffort: isValidEffortLevel(raw.estimated_effort)
   683→      ? raw.estimated_effort
   684→      : "medium",
   685→    status: isValidIdeaStatus(raw.status) ? raw.status : "draft",
   686→    promotedTo: raw.promoted_to || undefined,
   687→    created_at: raw.created_at,
   688→    affectedFiles: raw.affected_files,
   689→    existingPatterns: raw.existing_patterns,
   690→    buildsUpon: raw.builds_upon,
   691→    implementationApproach: raw.implementation_approach,
   692→    category: raw.category,
   693→    severity: raw.severity,
   694→    targetAudience: raw.target_audience,
   695→    relatedDocs: raw.related_docs,
   696→    metrics: raw.metrics,
   697→    uiComponents: raw.ui_components,
   698→    userStories: raw.user_stories,
   699→  };
   700→}
