   702→/**
   703→ * Convert raw session data from JSON to IdeaSession interface
   704→ */
   705→export function parseRawSession(raw: RawIdeaSession): IdeaSession {
   706→  return {
   707→    id: raw.id,
   708→    types: raw.types,
   709→    model: raw.model,
   710→    summary: {
   711→      total_ideas: raw.summary.total_ideas,
   712→      by_type: raw.summary.by_type,
   713→      by_status: {
