   715→        promoted: raw.summary.by_status.promoted || 0,
   716→        dismissed: raw.summary.by_status.dismissed || 0,
   717→      },
   718→    },
   719→    files: raw.files,
   720→    generated_at: raw.generated_at,
   721→    updated_at: raw.updated_at,
   722→  };
   723→}
