   169→// =============================================================================
   170→// Idea Type Management
   171→// =============================================================================
   172→
   173→/**
   174→ * Parse YAML frontmatter from a markdown file using gray-matter
   175→ *
   176→ * @param content - File content
   177→ * @returns Object with frontmatter (data) and body (content)
   178→ */
   179→function parseFrontmatter(content: string): {
   180→  frontmatter: Record<string, unknown>;
   181→  body: string;
   182→} {
   183→  try {
   184→    const parsed = matter(content);
   185→    return {
   186→      frontmatter: parsed.data as Record<string, unknown>,
   187→      body: parsed.content,
   188→    };
   189→  } catch {
   190→    return { frontmatter: {}, body: content };
   191→  }
   192→}
   193→
   194→/**
   195→ * Parse an Idea from parsed frontmatter and body content
   196→ *
   197→ * @param frontmatter - Parsed YAML frontmatter
   198→ * @param body - Markdown body content
   199→ * @returns Idea or null if invalid
   200→ */
   201→function parseIdeaFromFrontmatterAndBody(
   202→  frontmatter: Record<string, unknown>,
   203→  body: string
   204→): Idea | null {
   205→  if (!frontmatter.id) {
   206→    return null;
   207→  }
   208→
   209→  // Parse from frontmatter
   210→  const affectedFiles = Array.isArray(frontmatter.affected_files)
   211→    ? frontmatter.affected_files.map(String)
   212→    : [];
   213→  const existingPatterns = Array.isArray(frontmatter.existing_patterns)
   214→    ? frontmatter.existing_patterns.map(String)
   215→    : [];
   216→
   217→  // Body is the implementation approach
   218→  const implementationApproach = body.trim() || undefined;
   219→
   220→  const effortStr = String(frontmatter.estimated_effort || "medium");
   221→
   222→  return {
   223→    id: String(frontmatter.id),
   224→    type: String(frontmatter.type || ""),
   225→    name: frontmatter.name ? String(frontmatter.name) : undefined,
   226→    title: String(frontmatter.title || ""),
   227→    description: String(frontmatter.description || ""),
   228→    rationale: String(frontmatter.rationale || ""),
   229→    estimatedEffort: isValidEffortLevel(effortStr) ? effortStr : "medium",
   230→    status:
   231→      frontmatter.status === "promoted"
   232→        ? "promoted"
   233→        : frontmatter.status === "dismissed"
   234→          ? "dismissed"
   235→          : "draft",
   236→    promotedTo:
   237→      frontmatter.promoted_to && frontmatter.promoted_to !== "null"
   238→        ? String(frontmatter.promoted_to)
   239→        : undefined,
   240→    created_at: String(frontmatter.created_at || new Date().toISOString()),
   241→    affectedFiles: affectedFiles.length > 0 ? affectedFiles : undefined,
   242→    existingPatterns:
   243→      existingPatterns.length > 0 ? existingPatterns : undefined,
   244→    implementationApproach,
   245→    category: frontmatter.category
   246→      ? String(frontmatter.category)
   247→      : undefined,
   248→    severity: frontmatter.severity
   249→      ? String(frontmatter.severity)
   250→      : undefined,
   251→  };
   252→}
   253→
   254→/**
   255→ * Load an idea type from a file
   256→ *
   257→ * @param promptPath - Path to the prompt file
   258→ * @param source - Source of the idea type
   259→ * @returns IdeaType object or null if file doesn't exist
   260→ */
   261→function loadIdeaTypeFromFile(
   262→  promptPath: string,
   263→  source: IdeaTypeSource
   264→): IdeaType | null {
   265→  if (!existsSync(promptPath)) {
   266→    return null;
   267→  }
   268→
   269→  try {
   270→    const content = readFileSync(promptPath, "utf-8");
   271→    const { frontmatter } = parseFrontmatter(content);
   272→
   273→    // Get type name from frontmatter or filename
   274→    const fileName = promptPath.split("/").pop()?.replace(".md", "") || "";
   275→    const name = (frontmatter.name as string) || fileName;
   276→
   277→    return {
   278→      name,
   279→      description:
   280→        (frontmatter.description as string) ||
   281→        BUILTIN_TYPE_DESCRIPTIONS[name] ||
   282→        `Custom type: ${name}`,
   283→      maxIdeas: (frontmatter.max_ideas as number) || DEFAULT_MAX_IDEAS,
   284→      source,
   285→      promptPath,
   286→    };
   287→  } catch {
   288→    return null;
   289→  }
   290→}
   291→
   292→/**
   293→ * Check if a type name is a builtin type
   294→ */
   295→function isBuiltinTypeName(name: string): boolean {
   296→  return BUILTIN_IDEA_TYPES.includes(name as typeof BUILTIN_IDEA_TYPES[number]);
   297→}
   298→
   299→/**
   300→ * Get a single idea type by name
   301→ *
   302→ * Search order:
   303→ * 1. Custom types (docs/idea-types/*.md)
   304→ * 2. Built-in types (packages/core/templates/viben/idea-types/*.md)
   305→ *
   306→ * @param typeName - Name of the idea type
   307→ * @param repoRoot - Repository root path
   308→ * @returns IdeaType object or null if not found
   309→ */
   310→export function getIdeaType(typeName: string, repoRoot: string): IdeaType | null {
   311→  // First, try custom/project-local types in docs/idea-types/
   312→  const customPromptPath = getIdeaTypePromptPath(repoRoot, typeName);
   313→  if (existsSync(customPromptPath)) {
   314→    const source: IdeaTypeSource = isBuiltinTypeName(typeName) ? "builtin" : "custom";
   315→    return loadIdeaTypeFromFile(customPromptPath, source);
   316→  }
   317→
   318→  // Fallback to built-in types in packages/core/templates/viben/idea-types/
   319→  if (isBuiltinTypeName(typeName)) {
   320→    const builtinPromptPath = getBuiltinIdeaTypePromptPath(typeName);
   321→    if (existsSync(builtinPromptPath)) {
   322→      return loadIdeaTypeFromFile(builtinPromptPath, "builtin");
   323→    }
   324→  }
   325→
   326→  return null;
   327→}
   328→
   329→/**
   330→ * List all available idea types
   331→ *
   332→ * Search order:
   333→ * 1. Custom types in docs/idea-types/ (project-local)
   334→ * 2. Built-in types in packages/core/templates/viben/idea-types/ (fallback)
   335→ *
   336→ * @param repoRoot - Repository root path
   337→ * @returns Array of IdeaType objects
   338→ */
   339→export function listIdeaTypes(repoRoot: string): IdeaType[] {
   340→  const types: IdeaType[] = [];
   341→  const seenNames = new Set<string>();
   342→
   343→  // First, read custom/project-local types from docs/idea-types/
   344→  const customTypesDir = getIdeaTypesDir(repoRoot);
   345→  if (existsSync(customTypesDir)) {
   346→    try {
   347→      const files = readdirSync(customTypesDir);
   348→      for (const file of files) {
   349→        if (file.endsWith(".md")) {
   350→          const promptPath = join(customTypesDir, file);
   351→          const typeName = file.replace(".md", "");
   352→          const source: IdeaTypeSource = isBuiltinTypeName(typeName) ? "builtin" : "custom";
   353→          const ideaType = loadIdeaTypeFromFile(promptPath, source);
   354→          if (ideaType && !seenNames.has(ideaType.name)) {
   355→            types.push(ideaType);
   356→            seenNames.add(ideaType.name);
   357→          }
   358→        }
   359→      }
   360→    } catch {
   361→      // Ignore errors reading types directory
   362→    }
   363→  }
   364→
   365→  // Then, add built-in types that weren't overridden
   366→  for (const typeName of BUILTIN_IDEA_TYPES) {
   367→    if (!seenNames.has(typeName)) {
   368→      const builtinPromptPath = getBuiltinIdeaTypePromptPath(typeName);
   369→      if (existsSync(builtinPromptPath)) {
   370→        const ideaType = loadIdeaTypeFromFile(builtinPromptPath, "builtin");
   371→        if (ideaType) {
   372→          types.push(ideaType);
   373→          seenNames.add(ideaType.name);
   374→        }
   375→      }
   376→    }
   377→  }
   378→
   379→  return types.sort((a, b) => a.name.localeCompare(b.name));
   380→}
   381→
   382→/**
   383→ * Load the prompt content for an idea type
   384→ *
   385→ * @param ideaType - IdeaType object
   386→ * @returns Prompt content (without frontmatter) or null
   387→ */
   388→export function loadIdeaTypePrompt(ideaType: IdeaType): string | null {
   389→  if (!existsSync(ideaType.promptPath)) {
   390→    return null;
   391→  }
   392→
   393→  try {
   394→    const content = readFileSync(ideaType.promptPath, "utf-8");
   395→    const { body } = parseFrontmatter(content);
   396→    return body.trim();
   397→  } catch {
   398→    return null;
   399→  }
   400→}
