   405→
   406→/**
   407→ * Input for creating/updating an idea type file
   408→ */
   409→export interface IdeaTypeFileInput {
   410→  name?: string;
   411→  description?: string;
   412→  maxIdeas?: number;
   413→  promptContent?: string;
   414→}
   415→
   416→/**
   417→ * Create a new custom idea type
   418→ *
   419→ * Creates a markdown file with YAML frontmatter in docs/idea-types/.
   420→ *
   421→ * @param repoRoot - Repository root path
   422→ * @param input - Idea type data
   423→ * @returns Created IdeaType object
   424→ */
   425→export function createIdeaType(
   426→  repoRoot: string,
   427→  input: Required<Pick<IdeaTypeFileInput, "name" | "description">> & IdeaTypeFileInput
   428→): IdeaType {
   429→  const typesDir = getIdeaTypesDir(repoRoot);
   430→
   431→  // Ensure directory exists
   432→  if (!existsSync(typesDir)) {
   433→    mkdirSync(typesDir, { recursive: true });
   434→  }
   435→
   436→  const promptPath = join(typesDir, `${input.name}.md`);
   437→
   438→  // Build YAML frontmatter
   439→  const frontmatterLines = [
   440→    "---",
   441→    `name: ${input.name}`,
   442→    `description: ${input.description}`,
   443→  ];
   444→
   445→  if (input.maxIdeas !== undefined) {
   446→    frontmatterLines.push(`max_ideas: ${input.maxIdeas}`);
   447→  }
   448→
   449→  frontmatterLines.push("---");
   450→
   451→  // Combine frontmatter with prompt content
   452→  const content = frontmatterLines.join("\n") + "\n\n" + (input.promptContent || "");
   453→  writeFileSync(promptPath, content, "utf-8");
   454→
   455→  return {
   456→    name: input.name,
   457→    description: input.description,
   458→    maxIdeas: input.maxIdeas ?? DEFAULT_MAX_IDEAS,
   459→    source: "custom",
   460→    promptPath,
   461→  };
   462→}
   463→
   464→/**
   465→ * Update an existing idea type
   466→ *
   467→ * Updates the markdown file in docs/idea-types/.
   468→ *
   469→ * @param repoRoot - Repository root path
   470→ * @param typeName - Name of the type to update
   471→ * @param input - Fields to update
   472→ * @returns Updated IdeaType object
   473→ */
   474→export function updateIdeaType(
   475→  repoRoot: string,
   476→  typeName: string,
   477→  input: IdeaTypeFileInput
   478→): IdeaType {
   479→  const promptPath = getIdeaTypePromptPath(repoRoot, typeName);
   480→
   481→  if (!existsSync(promptPath)) {
   482→    throw new Error(`Idea type file not found: ${promptPath}`);
   483→  }
   484→
   485→  // Read existing content
   486→  const content = readFileSync(promptPath, "utf-8");
   487→  const { frontmatter, body } = parseFrontmatter(content);
   488→
   489→  // Update frontmatter fields
   490→  const newFrontmatter = {
   491→    name: typeName,
   492→    description: input.description ?? (frontmatter.description as string) ?? "",
   493→    max_ideas: input.maxIdeas ?? (frontmatter.max_ideas as number) ?? DEFAULT_MAX_IDEAS,
   494→  };
   495→
   496→  // Build new content
   497→  const frontmatterLines = [
   498→    "---",
   499→    `name: ${newFrontmatter.name}`,
   500→    `description: ${newFrontmatter.description}`,
   501→    `max_ideas: ${newFrontmatter.max_ideas}`,
   502→    "---",
   503→  ];
   504→
   505→  const newBody = input.promptContent !== undefined ? input.promptContent : body;
   506→  const newContent = frontmatterLines.join("\n") + "\n\n" + newBody.trim() + "\n";
   507→
   508→  writeFileSync(promptPath, newContent, "utf-8");
   509→
   510→  return {
   511→    name: typeName,
   512→    description: newFrontmatter.description,
   513→    maxIdeas: newFrontmatter.max_ideas,
   514→    source: isBuiltinTypeName(typeName) ? "builtin" : "custom",
   515→    promptPath,
   516→  };
   517→}
   518→
   519→/**
   520→ * Delete a custom idea type
   521→ *
   522→ * Removes the markdown file from docs/idea-types/.
   523→ *
   524→ * @param repoRoot - Repository root path
   525→ * @param typeName - Name of the type to delete
   526→ */
   527→export function deleteIdeaType(repoRoot: string, typeName: string): void {
   528→  const promptPath = getIdeaTypePromptPath(repoRoot, typeName);
   529→
   530→  if (!existsSync(promptPath)) {
   531→    throw new Error(`Idea type file not found: ${promptPath}`);
   532→  }
   533→
   534→  unlinkSync(promptPath);
   535→}
