   605→/**
   606→ * Read session metadata (idea.json)
   607→ *
   608→ * @param sessionDir - Session directory path
   609→ * @returns Session data or null if not found
   610→ */
   611→export function readSessionMetadata(sessionDir: string): IdeaSession | null {
   612→  const jsonPath = join(sessionDir, IDEA_JSON_FILE);
   613→  if (!existsSync(jsonPath)) {
   614→    return null;
   615→  }
   616→
   617→  try {
   618→    const content = readFileSync(jsonPath, "utf-8");
   619→    const raw = JSON.parse(content) as RawIdeaSession;
   620→    return parseRawSession(raw);
   621→  } catch {
