   674→/**
   675→ * List all idea sessions with their metadata
   676→ *
   677→ * @param repoRoot - Repository root path
   678→ * @returns Array of IdeaSessions, sorted by date descending
   679→ */
   680→export function listIdeaSessions(repoRoot: string): IdeaSession[] {
   681→  const sessionDirs = listSessions(repoRoot);
   682→  const sessions: IdeaSession[] = [];
   683→
   684→  for (const sessionDir of sessionDirs) {
   685→    const session = readSessionMetadata(sessionDir);
   686→    if (session) {
   687→      sessions.push(session);
   688→    }
   689→  }
   690→
   691→  return sessions;
   692→}
