   694→/**
   695→ * Write an idea session to its directory
   696→ *
   697→ * @param sessionDir - Path to session directory
   698→ * @param session - IdeaSession to write
   699→ */
   700→export function writeIdeaSession(
   701→  sessionDir: string,
   702→  session: IdeaSession
   703→): void {
   704→  // Convert to raw format for storage
   705→  const raw: RawIdeaSession = {
   706→    id: session.id,
   707→    types: session.types,
   708→    model: session.model,
   709→    summary: {
   710→      total_ideas: session.summary.total_ideas,
   711→      by_type: session.summary.by_type,
   712→      by_status: session.summary.by_status,
   713→    },
   714→    files: session.files,
   715→    generated_at: session.generated_at,
