   767→/**
   768→ * Write ideas to a markdown file
   769→ *
   770→ * Each idea is written as a section with YAML frontmatter.
   771→ *
   772→ * @param filePath - Path to write the file
   773→ * @param ideas - Array of ideas to write
   774→ */
   775→export function writeIdeasToFile(filePath: string, ideas: Idea[]): void {
   776→  const sections: string[] = [];
   777→
   778→  for (const idea of ideas) {
   779→    const frontmatter: string[] = [
   780→      "---",
   781→      `id: ${idea.id}`,
   782→      `type: ${idea.type}`,
   783→      `title: ${idea.title}`,
   784→      `description: ${idea.description}`,
   785→      `rationale: ${idea.rationale}`,
   786→      `estimated_effort: ${idea.estimatedEffort}`,
   787→      `status: ${idea.status}`,
   788→      `promoted_to: ${idea.promotedTo || "null"}`,
   789→      `created_at: ${idea.created_at}`,
   790→    ];
   791→
   792→    // Add affected files to frontmatter as YAML array
   793→    if (idea.affectedFiles && idea.affectedFiles.length > 0) {
   794→      frontmatter.push("affected_files:");
   795→      for (const file of idea.affectedFiles) {
   796→        frontmatter.push(`  - ${file}`);
   797→      }
   798→    }
   799→
   800→    // Add existing patterns to frontmatter as YAML array
   801→    if (idea.existingPatterns && idea.existingPatterns.length > 0) {
   802→      frontmatter.push("existing_patterns:");
   803→      for (const pattern of idea.existingPatterns) {
   804→        frontmatter.push(`  - ${pattern}`);
   805→      }
   806→    }
   807→
   808→    frontmatter.push("---");
   809→
   810→    // Body contains implementation approach directly
   811→    const body = idea.implementationApproach || "";
   812→
   813→    sections.push(frontmatter.join("\n") + "\n\n" + body);
   814→  }
   815→
   816→  const content = sections.join("\n---\n\n");
   817→  writeFileSync(filePath, content, "utf-8");
   818→}
