   829→  const ideaName = idea.name || idea.id;
   830→  const filePath = getSingleIdeaFilePath(sessionDir, idea.type, ideaName);
   831→  const fileName = getSingleIdeaFileName(idea.type, ideaName);
   832→
   833→  const frontmatter: string[] = [
   834→    "---",
