   893→/**
   894→ * Parse ideas from a markdown file
   895→ *
   896→ * Supports both:
   897→ * - Single idea per file (new format): starts with ---\nfrontmatter\n---
   898→ * - Multiple ideas per file (legacy format): multiple --- separated sections
   899→ *
   900→ * Uses gray-matter for robust YAML frontmatter parsing.
   901→ *
   902→ * @param filePath - Path to the idea file
   903→ * @returns Array of parsed ideas
   904→ */
   905→export function readIdeasFromFile(filePath: string): Idea[] {
   906→  if (!existsSync(filePath)) {
   907→    return [];
   908→  }
   909→
   910→  try {
   911→    const content = readFileSync(filePath, "utf-8").trim();
   912→
   913→    // Use gray-matter to parse the file
   914→    const { frontmatter, body } = parseFrontmatter(content);
   915→
   916→    // If frontmatter has an id, this is a single-idea file
   917→    if (frontmatter.id) {
   918→      const idea = parseIdeaFromFrontmatterAndBody(frontmatter, body);
   919→      if (idea) {
   920→        return [idea];
   921→      }
   922→    }
   923→
   924→    // Legacy format: multiple ideas separated by \n---\n
   925→    // This happens when ideas were written with writeIdeasToFile (multiple per file)
   926→    const ideas: Idea[] = [];
   927→    const sections = content.split(/\n---\n+/);
   928→
   929→    for (const section of sections) {
   930→      const trimmed = section.trim();
   931→      if (!trimmed) {
   932→        continue;
   933→      }
   934→
   935→      // Section might start with --- or not (if it was split)
   936→      const sectionToparse = trimmed.startsWith("---")
   937→        ? trimmed
   938→        : "---\n" + trimmed;
   939→      const { frontmatter: fm, body: bd } = parseFrontmatter(sectionToparse);
   940→
   941→      if (fm.id) {
   942→        const idea = parseIdeaFromFrontmatterAndBody(fm, bd);
   943→        if (idea) {
   944→          ideas.push(idea);
   945→        }
   946→      }
   947→    }
   948→
   949→    return ideas;
   950→  } catch {
   951→    return [];
   952→  }
   953→}
