   955→/**
   956→ * Get all ideas from a session
   957→ *
   958→ * @param sessionDir - Session directory path
   959→ * @returns Array of all ideas in the session
   960→ */
   961→export function getAllIdeasFromSession(sessionDir: string): Idea[] {
   962→  const ideas: Idea[] = [];
   963→
   964→  try {
   965→    const files = readdirSync(sessionDir);
   966→    for (const file of files) {
   967→      if (file.startsWith(IDEA_FILE_PREFIX) && file.endsWith(".md")) {
   968→        const filePath = join(sessionDir, file);
   969→        const fileIdeas = readIdeasFromFile(filePath);
   970→        ideas.push(...fileIdeas);
   971→      }
   972→    }
   973→  } catch {
   974→    // Ignore errors
   975→  }
   976→
   977→  return ideas;
   978→}
