   988→export function findIdeaById(
   989→  repoRoot: string,
   990→  ideaId: string,
   991→  customOutput?: string
   992→): { idea: Idea; sessionDir: string; filePath: string } | null {
   993→  const sessions = listSessions(repoRoot, customOutput);
   994→
   995→  for (const sessionDir of sessions) {
   996→    try {
   997→      const files = readdirSync(sessionDir);
   998→      for (const file of files) {
   999→        if (file.startsWith(IDEA_FILE_PREFIX) && file.endsWith(".md")) {
  1000→          const filePath = join(sessionDir, file);
  1001→          const ideas = readIdeasFromFile(filePath);
  1002→          const found = ideas.find((i) => i.id === ideaId);
  1003→          if (found) {
  1004→            return { idea: found, sessionDir, filePath };
  1005→          }
  1006→        }
  1007→      }
  1008→    } catch {
  1009→      // Continue to next session
  1010→    }
  1011→  }
  1012→
  1013→  return null;
  1014→}
