     1→/**
     2→ * Service API Keys routes
     3→ *
     4→ * Provides HTTP API for managing service API keys used for external client authentication.
     5→ * Keys are stored in ~/.config/browse-mcp/service_keys.json
     6→ */
     7→import type { FastifyInstance } from "fastify";
     8→import { readFile, writeFile, mkdir } from "node:fs/promises";
     9→import { existsSync } from "node:fs";
    10→import { join } from "node:path";
    11→import { homedir } from "node:os";
    12→import { randomUUID } from "node:crypto";
    13→
    14→// ============================================================================
    15→// Types
    16→// ============================================================================
    17→
    18→interface ServiceApiKey {
    19→  id: string;
    20→  name: string;
    21→  key: string;
    22→  key_prefix: string;
    23→  created_at: string;
    24→  last_used: string | null;
    25→}
    26→
    27→interface ServiceKeysStore {
    28→  keys: ServiceApiKey[];
    29→}
    30→
    31→// ============================================================================
    32→// Helper Functions
    33→// ============================================================================
    34→
    35→/**
    36→ * Get the service keys file path
    37→ */
    38→function getKeysFilePath(): string {
    39→  const configDir = process.platform === "darwin"
    40→    ? join(homedir(), "Library", "Application Support", "browse-mcp")
    41→    : process.platform === "win32"
    42→      ? join(process.env.APPDATA || join(homedir(), "AppData", "Roaming"), "browse-mcp")
    43→      : join(homedir(), ".config", "browse-mcp");
    44→
    45→  return join(configDir, "service_keys.json");
    46→}
    47→
    48→/**
    49→ * Load service keys from file
    50→ */
    51→async function loadKeys(): Promise<ServiceApiKey[]> {
    52→  const path = getKeysFilePath();
    53→  try {
    54→    if (!existsSync(path)) {
    55→      return [];
    56→    }
    57→    const content = await readFile(path, "utf-8");
    58→    const store: ServiceKeysStore = JSON.parse(content);
    59→    return store.keys;
    60→  } catch {
    61→    return [];
    62→  }
    63→}
    64→
    65→/**
    66→ * Save service keys to file
    67→ */
    68→async function saveKeys(keys: ServiceApiKey[]): Promise<void> {
    69→  const path = getKeysFilePath();
    70→  const dir = join(path, "..");
    71→
    72→  if (!existsSync(dir)) {
    73→    await mkdir(dir, { recursive: true });
    74→  }
    75→
    76→  const store: ServiceKeysStore = { keys };
    77→  await writeFile(path, JSON.stringify(store, null, 2), "utf-8");
    78→}
    79→
    80→/**
    81→ * Generate a new API key
    82→ */
    83→function generateApiKey(): string {
    84→  const chars = "abcdefghijklmnopqrstuvwxyz0123456789";
    85→  let randomPart = "";
    86→  for (let i = 0; i < 32; i++) {
    87→    randomPart += chars.charAt(Math.floor(Math.random() * chars.length));
    88→  }
    89→  return `bm_live_${randomPart}`;
    90→}
    91→
    92→/**
    93→ * Create key prefix for display
    94→ */
    95→function createKeyPrefix(key: string): string {
    96→  if (key.length > 12) {
    97→    return `${key.substring(0, 8)}...${key.substring(key.length - 4)}`;
    98→  }
    99→  return "****";
   100→}
   101→
   102→/**
   103→ * Get current timestamp string
   104→ */
   105→function getCurrentTimestamp(): string {
   106→  return new Date().toISOString().replace("T", " ").substring(0, 19);
   107→}
   108→
   109→// ============================================================================
   110→// Routes
   111→// ============================================================================
   112→
   113→export function registerServiceKeysRoutes(fastify: FastifyInstance): void {
   114→  /**
   115→   * Get all service API keys
   116→   * GET /api/service-keys
   117→   */
   118→  fastify.get("/api/service-keys", async () => {
   119→    const keys = await loadKeys();
   120→    return { keys };
   121→  });
   122→
   123→  /**
   124→   * Create a new service API key
   125→   * POST /api/service-keys
   126→   */
   127→  fastify.post<{
   128→    Body: { name: string };
   129→  }>("/api/service-keys", async (request, reply) => {
   130→    const { name } = request.body;
   131→
   132→    if (!name) {
   133→      reply.code(400);
   134→      return { error: "Name is required" };
   135→    }
   136→
   137→    const keys = await loadKeys();
   138→
   139→    const key = generateApiKey();
   140→    const newKey: ServiceApiKey = {
   141→      id: randomUUID(),
   142→      name,
   143→      key,
   144→      key_prefix: createKeyPrefix(key),
   145→      created_at: getCurrentTimestamp(),
   146→      last_used: null,
   147→    };
   148→
   149→    keys.push(newKey);
   150→    await saveKeys(keys);
   151→
   152→    reply.code(201);
   153→    return newKey;
   154→  });
   155→
   156→  /**
   157→   * Get a service API key by ID
   158→   * GET /api/service-keys/:keyId
   159→   */
   160→  fastify.get<{
   161→    Params: { keyId: string };
   162→  }>("/api/service-keys/:keyId", async (request, reply) => {
   163→    const { keyId } = request.params;
   164→    const keys = await loadKeys();
   165→    const key = keys.find((k) => k.id === keyId);
   166→
   167→    if (!key) {
   168→      reply.code(404);
   169→      return { error: "Key not found" };
   170→    }
   171→
   172→    return key;
   173→  });
   174→
   175→  /**
   176→   * Delete a service API key
   177→   * DELETE /api/service-keys/:keyId
   178→   */
   179→  fastify.delete<{
   180→    Params: { keyId: string };
   181→  }>("/api/service-keys/:keyId", async (request, reply) => {
   182→    const { keyId } = request.params;
   183→    const keys = await loadKeys();
   184→    const filtered = keys.filter((k) => k.id !== keyId);
   185→
   186→    if (filtered.length === keys.length) {
   187→      reply.code(404);
   188→      return { error: "Key not found" };
   189→    }
   190→
   191→    await saveKeys(filtered);
   192→    return { deleted: keyId };
   193→  });
   194→
   195→  /**
   196→   * Validate a service API key
   197→   * POST /api/service-keys/validate
   198→   */
   199→  fastify.post<{
   200→    Body: { api_key: string };
   201→  }>("/api/service-keys/validate", async (request) => {
   202→    const { api_key } = request.body;
   203→    const keys = await loadKeys();
   204→    const valid = keys.some((k) => k.key === api_key);
   205→    return { valid };
   206→  });
   207→
   208→  /**
   209→   * Update last used timestamp for a key
   210→   * POST /api/service-keys/:keyId/usage
   211→   */
   212→  fastify.post<{
   213→    Params: { keyId: string };
   214→  }>("/api/service-keys/:keyId/usage", async (request, reply) => {
   215→    const { keyId } = request.params;
   216→    const keys = await loadKeys();
   217→    const keyIndex = keys.findIndex((k) => k.id === keyId);
   218→
   219→    if (keyIndex === -1) {
   220→      reply.code(404);
   221→      return { error: "Key not found" };
   222→    }
   223→
   224→    keys[keyIndex].last_used = getCurrentTimestamp();
   225→    await saveKeys(keys);
   226→
   227→    return { updated: keyId };
   228→  });
   229→}
   230→

